SELECT "nct", "author", "year", "pubmed_id", "follow_up_type", "follow_up_duration_overall_months" AS "median_follow_up_months", "follow_up_duration_rx_months" AS "rx_arm_months", "follow_up_duration_control_months" AS "control_arm_months" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%Hodgkin Lymphoma%' AND "follow_up_type" IS NOT NULL AND "follow_up_duration_overall_months" IS NOT NULL AND "follow_up_duration_rx_months" IS NOT NULL AND "follow_up_duration_control_months" IS NOT NULL